/* Live loadout workspace uses the existing navy working surface. */
.damage-gauges{display:grid;gap:16px;padding:4px 0 22px}.gauge-label{display:flex;justify-content:space-between;gap:12px;font-size:.875rem;line-height:1.65;margin-bottom:7px;color:#c0d3e8}.gauge-label b{display:block;color:#fff;font-size:1rem;font-variant-numeric:tabular-nums}.gauge-label>span:last-child{text-align:right}.gauge-track{height:9px;border-radius:9px;background:#40546e;overflow:hidden}.gauge-track>span{display:block;height:100%;width:0;background:#f47c37;border-radius:inherit;transition:width .18s ease}.gauge-track.critical>span{background:#72c6ee}.unified-start{width:100%;margin-top:14px;min-height:46px}.unified-workspace{min-width:0;border:1px solid #bacbdd;border-radius:8px;overflow:hidden;background:#fff}.unified-toolbar{display:flex;gap:8px;align-items:center;padding:12px;border-bottom:1px solid #d9e3ee;flex-wrap:wrap}.unified-toolbar strong{margin-right:auto}.unified-workspace iframe{display:block;border:0;width:100%;height:calc(100vh - 96px);min-height:620px}.unified-mode main{max-width:1900px;padding:16px}.unified-mode .calculator-layout{grid-template-columns:minmax(0,1fr) 370px}.unified-mode #calculator{display:none}.unified-mode.unified-settings #calculator{display:block;grid-column:1;grid-row:2}.unified-mode.unified-settings .unified-workspace iframe{display:none}.unified-mode .results{grid-column:2;grid-row:1 / span 2;position:sticky;top:16px;max-height:calc(100vh - 32px);overflow:auto}.unified-mode .primary-result{display:none}.unified-mode .result-notes>p:nth-child(2){display:none}.unified-summary h3{margin:0 0 14px;font-size:1rem}#unifiedStats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px 8px}#unifiedStats span,#unifiedStats small{display:block;font-size:.875rem;color:#55718e}#unifiedStats strong{display:block;font-size:1.1rem;margin:4px 0;font-variant-numeric:tabular-nums}#unifiedBonuses{display:flex;gap:6px;flex-wrap:wrap;margin-top:16px}#unifiedBonuses span{font-size:.875rem;background:#edf4fb;border:1px solid #d6e4f1;border-radius:4px;padding:4px 6px}.unified-unresolved{border-color:#d9b37f}.unified-unresolved summary{color:#895719}.unified-unresolved ul{padding-left:20px;font-size:.875rem;line-height:1.65}.unified-unresolved p{margin:4px 0}.unified-unresolved li{margin:12px 0}
