  for(const id of ['attackBase','runtimeStatPercent']){$(id).disabled=mode!=='layers';$(id).required=mode==='layers';}
  $('settledAttack').disabled=mode!=='settlement';$('settledAttack').required=mode==='settlement';
  $('attack').required=mode==='panel';
